// Deduplicate initial records by normalized full name
const seenNames = new Set<string>();
export const INITIAL_INVITATIONS_DATA: InvitationRecord[] = RAW_INITIAL_INVITATIONS_DATA.filter((item) => {
  const norm = item.fullName.trim().toLowerCase();
  if (!norm || seenNames.has(norm)) {
    return false;
  }
  seenNames.add(norm);
  return true;
}).map((item, idx) => ({
  ...item,
  serialNo: idx + 1
}));

